def createparser():
    """Create an ArgumentParser for the pysemver command-line interface."""
    import argparse
    parser = argparse.ArgumentParser(prog='pysemver', description='Semantic Versioning utilities')
    subparsers = parser.add_subparsers(dest='command')

    # bump command
    bump_parser = subparsers.add_parser('bump', help='Bump a version component')
    bump_parser.add_argument('version', help='Version string to bump')
    bump_parser.add_argument('component', choices=['major', 'minor', 'patch', 'prerelease', 'build'], help='Component to bump')
    bump_parser.add_argument('-t', '--token', default=None, help='Token for prerelease or build increment')

    # replace command
    replace_parser = subparsers.add_parser('replace', help='Replace components of a version')
    replace_parser.add_argument('version', help='Version string to replace')
    replace_parser.add_argument('-m', '--major', type=int, help='New major')
    replace_parser.add_argument('-n', '--minor', type=int, help='New minor')
    replace_parser.add_argument('-p', '--patch', type=int, help='New patch')
    replace_parser.add_argument('-r', '--prerelease', help='New prerelease')
    replace_parser.add_argument('-b', '--build', help='New build')

    return parser


def process(args=None):
    """Process command-line arguments and perform actions."""
    import sys
    parser = createparser()
    if args is None:
        args = sys.argv[1:]
    ns = parser.parse_args(args)
    if ns.command == 'bump':
        component = ns.component
        token = ns.token
        if component == 'major':
            print(bump_major(ns.version))
        elif component == 'minor':
            print(bump_minor(ns.version))
        elif component == 'patch':
            print(bump_patch(ns.version))
        elif component == 'prerelease':
            print(bump_prerelease(ns.version, token=token or 'rc'))
        elif component == 'build':
            print(bump_build(ns.version, token=token or 'build'))
    elif ns.command == 'replace':
        kwargs = {}
        if ns.major is not None:
            kwargs['major'] = ns.major
        if ns.minor is not None:
            kwargs['minor'] = ns.minor
        if ns.patch is not None:
            kwargs['patch'] = ns.patch
        if ns.prerelease is not None:
            kwargs['prerelease'] = ns.prerelease
        if ns.build is not None:
            kwargs['build'] = ns.build
        print(replace(ns.version, **kwargs))
    else:
        parser.print_help()


def main():
    """Entry point for pysemver command-line interface."""
    process()
